renames.to:
// The last base64url char of a 32-byte verifier carries only 4 bits, so ~6% of verifiers
// ALREADY end in "A" — replacing it with "A" left the string unchanged, made this "wrong"
// verifier the RIGHT one, and failed the rail about one run in seventeen. Mutate to a char
// that cannot equal the original.
const wrongVerifier = verifier.slice(0, -1) + (verifier.endsWith("A") ? "B" : "A");
const wrong = await redeem(base, { code, code_verifier: wrongVerifier });
